import 'dart:io';
import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import 'app_state.dart';
import 'security_screen.dart';
class MoreScreen extends StatelessWidget{const MoreScreen({super.key});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('More')),body:ListView(children:[ListTile(leading:const Icon(Icons.business),title:const Text('Business profile'),onTap:()=>_info(c)),ListTile(leading:const Icon(Icons.security),title:const Text('Security / PIN'),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>const SecurityScreen()))),ListTile(leading:const Icon(Icons.dark_mode),title:const Text('Theme'),trailing:DropdownButton<ThemeMode>(value:c.watch<AppState>().themeMode,items:const[DropdownMenuItem(value:ThemeMode.system,child:Text('System')),DropdownMenuItem(value:ThemeMode.light,child:Text('Light')),DropdownMenuItem(value:ThemeMode.dark,child:Text('Dark'))],onChanged:(v){if(v!=null)c.read<AppState>().setTheme(v);})]),ListTile(leading:const Icon(Icons.backup),title:const Text('Export JSON backup'),onTap:()async{final data=await c.read<AppState>().db.exportJson();await showDialog(context:c,builder:(_)=>AlertDialog(title:const Text('Backup data'),content:SingleChildScrollView(child:Text(data)),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Close'))]));}),const ListTile(title:Text('Digital Khata v1.0.0'))]));}
void _info(BuildContext c){final b=c.read<AppState>().db.get('business');showDialog(context:c,builder:(_)=>AlertDialog(title:const Text('Business profile'),content:Text(b==null?'Not set':b.toString()),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Close'))]));}}
